SELECT CASE WHEN o.discount >= 0.4 THEN 'high' WHEN o.discount >= 0.06 THEN 'mid' ELSE 'low' END AS discount_bucket, o.customer_id, ROUND((100 * SUM(CASE WHEN p.status = 'SUCCESS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_success FROM payments p LEFT JOIN orders o ON o.id = p.order_id WHERE HOUR(p.paid_at) BETWEEN 12 AND 15 GROUP BY CASE WHEN o.discount >= 0.4 THEN 'high' WHEN o.discount >= 0.06 THEN 'mid' ELSE 'low' END, o.customer_id ORDER BY discount_bucket DESC;
